/* @autogenerated */
package net.civeira.phylax.feature.observe.store;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * Level of a trace: the most severe of its logs, or ERROR if one of its spans failed. Every log and
 * span of a trace is kept as long as the level of its trace asks
 * ({@link RetentionPolicy.LevelRetention}): the DEBUG log of a request that ended in an error lives
 * as long as the error.
 *
 * <ul>
 * <li>A log counts with its own level; a span adds nothing unless it failed (ERROR).</li>
 * <li>The level of a row is the highest of its own and the one of its trace; a span of a trace
 * without logs nor errors counts as INFO.</li>
 * </ul>
 * This instance remembers the level of the last traces seen (at most {@code MAX}), so the stores
 * know which traces rise with each batch.
 */
public final class TraceLevels {

  public static final int NONE = 0;
  public static final int DEBUG = 1;
  public static final int INFO = 2;
  public static final int WARN = 3;
  public static final int ERROR = 4;

  private static final int MAX = 200_000;

  private final Map<String, Integer> known = new LinkedHashMap<>(1024, 0.75f, true) {
    @Override
    protected boolean removeEldestEntry(final Map.Entry<String, Integer> eldest) {
      return size() > MAX;
    }
  };

  /** Level of the name of a log level (TRACE counts as DEBUG and FATAL as ERROR). */
  public static int of(final String level) {
    String name = null == level ? "" : level.toUpperCase(Locale.ROOT);
    switch (name) {
      case "TRACE":
      case "DEBUG":
        return DEBUG;
      case "WARN":
      case "WARNING":
        return WARN;
      case "ERROR":
      case "FATAL":
      case "SEVERE":
        return ERROR;
      default:
        return INFO;
    }
  }

  public static int of(final ObsLog log) {
    return of(log.level());
  }

  public static int of(final ObsSpan span) {
    return span.isError() ? ERROR : NONE;
  }

  /**
   * The level a row is kept with: its own or the one of its trace, INFO if neither says anything.
   */
  public static int effective(final int own, final int trace) {
    int level = Math.max(own, trace);
    return NONE == level ? INFO : level;
  }

  public static String name(final int level) {
    return new String[] {"NONE", "DEBUG", "INFO", "WARN", "ERROR"}[Math.max(0,
        Math.min(ERROR, level))];
  }

  /** The level known of a trace ({@link #NONE} if it has not been seen). */
  public synchronized int level(final String traceId) {
    Integer level = null == traceId ? null : known.get(traceId);
    return null == level ? NONE : level;
  }

  /**
   * Takes the levels of a batch and returns the traces whose level rose, with their new level: the
   * ones already seen, and the ones new at WARN or above (their earlier rows may be from before a
   * restart). The stores mark the rows they already have with it.
   */
  public synchronized Map<String, Integer> raise(final List<ObsLog> logs,
      final List<ObsSpan> spans) {
    Map<String, Integer> raised = new LinkedHashMap<>();
    for (ObsLog log : logs) {
      raise(log.traceId(), of(log), raised);
    }
    for (ObsSpan span : spans) {
      raise(span.traceId(), of(span), raised);
    }
    return raised;
  }

  private void raise(final String traceId, final int level, final Map<String, Integer> raised) {
    if (null == traceId || traceId.isEmpty() || NONE == level) {
      return;
    }
    Integer previous = known.get(traceId);
    if (null != previous && previous >= level) {
      return;
    }
    known.put(traceId, level);
    if (null != previous || level >= WARN) {
      raised.put(traceId, level);
    }
  }
}
